-- Site and Studio themes with a personality, not a palette swap.
--
-- Each theme now sets its palette, its faces (headings, body, labels), its
-- radius scale and its elevation (shadow-* utilities read
-- --shadow-elevation-1..3). The same catalogue serves Site appearance
-- (Tethyr itself) and a Studio's own theme. Existing ids keep working;
-- Minimal, Developer, Neon and Studio Light are renamed to the character
-- they now have (Mono, Obsidian, Signal, Studio). Five themes are new.

INSERT INTO public.themes (id, name, description, tokens, created_by) VALUES
  ('00000000-0000-0000-0000-000000000010', 'Mono', 'Almost entirely monochrome. Black ink, white page, nothing to distract from the work.', '{"colors":{"background":"#fafafa","foreground":"#0a0a0a","card":"#ffffff","border":"#d4d4d4","primary":"#0a0a0a"},"typography":{"headingFont":"\"Inter\", ui-sans-serif, system-ui, sans-serif","bodyFont":"\"Inter\", ui-sans-serif, system-ui, sans-serif","monoFont":"\"JetBrains Mono\", ui-monospace, SFMono-Regular, Consolas, monospace"},"borders":{"radius":{"sm":"1px","md":"2px","lg":"2px","xl":"3px","2xl":"3px","3xl":"4px","4xl":"4px"}},"shadows":{"elevation-1":"none","elevation-2":"0 1px 0 rgb(0 0 0 / 0.08)","elevation-3":"0 10px 30px -14px rgb(0 0 0 / 0.3)"}}'::jsonb, null),
  ('00000000-0000-0000-0000-000000000011', 'Obsidian', 'Dark, sharp and technical. Quiet surfaces, precise edges, a cool blue for what matters.', '{"colors":{"background":"#0b0c0e","foreground":"#e7e9ec","card":"#121418","border":"#262a31","primary":"#7aa2f7"},"typography":{"headingFont":"\"Space Grotesk\", \"Inter\", ui-sans-serif, system-ui, sans-serif","bodyFont":"\"Inter\", ui-sans-serif, system-ui, sans-serif","monoFont":"\"JetBrains Mono\", ui-monospace, SFMono-Regular, Consolas, monospace"},"borders":{"radius":{"sm":"1px","md":"2px","lg":"3px","xl":"4px","2xl":"4px","3xl":"5px","4xl":"6px"}},"shadows":{"elevation-1":"0 1px 0 rgb(0 0 0 / 0.5)","elevation-2":"0 6px 16px -8px rgb(0 0 0 / 0.7)","elevation-3":"0 18px 40px -16px rgb(0 0 0 / 0.8)"}}'::jsonb, null),
  ('00000000-0000-0000-0000-000000000012', 'Terminal', 'Technical and grid-born: phosphor green on black, monospace headings, square everything.', '{"colors":{"background":"#050805","foreground":"#c8f7c5","card":"#0b120b","border":"#1d3a1f","primary":"#5cff7a"},"typography":{"headingFont":"\"JetBrains Mono\", ui-monospace, SFMono-Regular, Consolas, monospace","bodyFont":"\"Inter\", ui-sans-serif, system-ui, sans-serif","monoFont":"\"JetBrains Mono\", ui-monospace, SFMono-Regular, Consolas, monospace"},"borders":{"radius":{"sm":"0px","md":"0px","lg":"0px","xl":"0px","2xl":"0px","3xl":"0px","4xl":"0px"}},"shadows":{"elevation-1":"none","elevation-2":"0 0 0 1px var(--border)","elevation-3":"0 0 0 1px var(--border-strong)"}}'::jsonb, null),
  ('00000000-0000-0000-0000-000000000013', 'Midnight', 'Dark and atmospheric. Deep navy, soft light, refined serif headings.', '{"colors":{"background":"#0b1220","foreground":"#e2e8f0","card":"#111a2b","border":"#25324a","primary":"#8ab4ff"},"typography":{"headingFont":"\"Fraunces\", Georgia, \"Times New Roman\", serif","bodyFont":"\"Inter\", ui-sans-serif, system-ui, sans-serif","monoFont":"\"JetBrains Mono\", ui-monospace, SFMono-Regular, Consolas, monospace"},"borders":{"radius":{"sm":"3px","md":"4px","lg":"6px","xl":"8px","2xl":"8px","3xl":"10px","4xl":"12px"}},"shadows":{"elevation-1":"0 1px 2px rgb(0 0 0 / 0.4)","elevation-2":"0 8px 24px -10px rgb(0 0 0 / 0.6)","elevation-3":"0 24px 48px -18px rgb(0 0 0 / 0.7)"}}'::jsonb, null),
  ('00000000-0000-0000-0000-000000000017', 'Signal', 'High contrast with an energetic accent. Dark, bold and loud where it counts.', '{"colors":{"background":"#0a0a0a","foreground":"#ffffff","card":"#141414","border":"#3a3a3a","primary":"#ff5c00"},"typography":{"headingFont":"\"Sora\", \"Inter\", ui-sans-serif, system-ui, sans-serif","bodyFont":"\"Inter\", ui-sans-serif, system-ui, sans-serif","monoFont":"\"JetBrains Mono\", ui-monospace, SFMono-Regular, Consolas, monospace"},"borders":{"radius":{"sm":"0px","md":"1px","lg":"2px","xl":"2px","2xl":"2px","3xl":"3px","4xl":"4px"}},"shadows":{"elevation-1":"2px 2px 0 rgb(255 92 0 / 0.55)","elevation-2":"4px 4px 0 rgb(255 92 0 / 0.55)","elevation-3":"6px 6px 0 rgb(255 92 0 / 0.55)"}}'::jsonb, null),
  ('00000000-0000-0000-0000-000000000020', 'Studio', 'Creative and a little experimental. Warm paper, rounded shapes, a vivid ember accent.', '{"colors":{"background":"#faf8f4","foreground":"#1c1a17","card":"#ffffff","border":"#e4ded3","primary":"#d9480f"},"typography":{"headingFont":"\"Sora\", \"Inter\", ui-sans-serif, system-ui, sans-serif","bodyFont":"\"DM Sans\", \"Inter\", ui-sans-serif, system-ui, sans-serif","monoFont":"\"JetBrains Mono\", ui-monospace, SFMono-Regular, Consolas, monospace"},"borders":{"radius":{"sm":"4px","md":"6px","lg":"10px","xl":"12px","2xl":"14px","3xl":"16px","4xl":"20px"}},"shadows":{"elevation-1":"0 1px 2px rgb(60 40 20 / 0.08)","elevation-2":"0 8px 20px -8px rgb(60 40 20 / 0.18)","elevation-3":"0 20px 44px -16px rgb(60 40 20 / 0.24)"}}'::jsonb, null),
  ('00000000-0000-0000-0000-000000000021', 'Paper', 'Warm, tactile and literary. Cream pages, ink, serif headings and fine rules.', '{"colors":{"background":"#f6f1e7","foreground":"#2a241c","card":"#fbf8f1","border":"#d8cdb8","primary":"#8a3b12"},"typography":{"headingFont":"\"Fraunces\", Georgia, \"Times New Roman\", serif","bodyFont":"\"Inter\", ui-sans-serif, system-ui, sans-serif","monoFont":"\"JetBrains Mono\", ui-monospace, SFMono-Regular, Consolas, monospace"},"borders":{"radius":{"sm":"1px","md":"2px","lg":"3px","xl":"4px","2xl":"4px","3xl":"5px","4xl":"6px"}},"shadows":{"elevation-1":"0 1px 0 rgb(60 40 10 / 0.08)","elevation-2":"0 2px 0 rgb(60 40 10 / 0.08), 0 6px 18px -10px rgb(60 40 10 / 0.2)","elevation-3":"0 16px 36px -18px rgb(60 40 10 / 0.3)"}}'::jsonb, null),
  ('00000000-0000-0000-0000-000000000022', 'Graphite', 'Monochrome, precise and modern. Cool greys, crisp edges, ink as the accent.', '{"colors":{"background":"#f3f4f5","foreground":"#16181b","card":"#fbfbfc","border":"#c9cdd2","primary":"#16181b"},"typography":{"headingFont":"\"Inter\", ui-sans-serif, system-ui, sans-serif","bodyFont":"\"Inter\", ui-sans-serif, system-ui, sans-serif","monoFont":"\"JetBrains Mono\", ui-monospace, SFMono-Regular, Consolas, monospace"},"borders":{"radius":{"sm":"2px","md":"3px","lg":"4px","xl":"6px","2xl":"6px","3xl":"8px","4xl":"10px"}},"shadows":{"elevation-1":"0 1px 2px rgb(16 24 32 / 0.08)","elevation-2":"0 4px 12px -4px rgb(16 24 32 / 0.14)","elevation-3":"0 16px 32px -12px rgb(16 24 32 / 0.2)"}}'::jsonb, null),
  ('00000000-0000-0000-0000-000000000023', 'Forest', 'Natural, grounded and quiet. Moss, bark and soft light.', '{"colors":{"background":"#f2f4ef","foreground":"#1d2a1f","card":"#f9faf6","border":"#cdd6c7","primary":"#2f6b45"},"typography":{"headingFont":"\"Manrope\", \"Inter\", ui-sans-serif, system-ui, sans-serif","bodyFont":"\"Inter\", ui-sans-serif, system-ui, sans-serif","monoFont":"\"JetBrains Mono\", ui-monospace, SFMono-Regular, Consolas, monospace"},"borders":{"radius":{"sm":"3px","md":"5px","lg":"8px","xl":"10px","2xl":"10px","3xl":"12px","4xl":"14px"}},"shadows":{"elevation-1":"0 1px 2px rgb(20 40 20 / 0.08)","elevation-2":"0 8px 20px -10px rgb(20 40 20 / 0.18)","elevation-3":"0 20px 40px -18px rgb(20 40 20 / 0.24)"}}'::jsonb, null),
  ('00000000-0000-0000-0000-000000000024', 'Archive', 'Editorial and understated, like a well-kept catalogue. Square edges, no shadows.', '{"colors":{"background":"#efece6","foreground":"#22201c","card":"#f7f5f0","border":"#cfc7b8","primary":"#6b4f2a"},"typography":{"headingFont":"\"Playfair Display\", Georgia, \"Times New Roman\", serif","bodyFont":"\"Inter\", ui-sans-serif, system-ui, sans-serif","monoFont":"\"JetBrains Mono\", ui-monospace, SFMono-Regular, Consolas, monospace"},"borders":{"radius":{"sm":"0px","md":"1px","lg":"1px","xl":"2px","2xl":"2px","3xl":"2px","4xl":"3px"}},"shadows":{"elevation-1":"none","elevation-2":"0 0 0 1px var(--border)","elevation-3":"0 0 0 1px var(--border-strong)"}}'::jsonb, null),
  ('00000000-0000-0000-0000-000000000025', 'Gallery', 'Artistic and spacious. White walls, black type, nothing between visitors and the images.', '{"colors":{"background":"#ffffff","foreground":"#111111","card":"#ffffff","border":"#ebebeb","primary":"#111111"},"typography":{"headingFont":"\"DM Sans\", \"Inter\", ui-sans-serif, system-ui, sans-serif","bodyFont":"\"DM Sans\", \"Inter\", ui-sans-serif, system-ui, sans-serif","monoFont":"\"JetBrains Mono\", ui-monospace, SFMono-Regular, Consolas, monospace"},"borders":{"radius":{"sm":"0px","md":"0px","lg":"0px","xl":"0px","2xl":"0px","3xl":"0px","4xl":"0px"}},"shadows":{"elevation-1":"none","elevation-2":"none","elevation-3":"0 24px 60px -30px rgb(0 0 0 / 0.25)"}}'::jsonb, null)
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  tokens = EXCLUDED.tokens,
  updated_at = now();

UPDATE public.themes
SET description = 'Clean, contemporary and human. Tethyr''s own paper, ink and teal.'
WHERE id = '00000000-0000-0000-0000-000000000001';
